WITH flattened AS (SELECT id, plan, effective_from, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers), cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), effective_from) days_since_effective_from FROM flattened WHERE plan != 'enterprise'), with_windows AS (SELECT *, MIN(days_since_effective_from) OVER (PARTITION BY plan) plan_min_days_since_effective_from FROM cleaned WHERE tier_value IS NOT NULL), filtered AS (SELECT id, tier_value, days_since_effective_from, plan_min_days_since_effective_from, COALESCE(tier_value, 0) tier_value_filled, COALESCE(tier_value, 0) tier_value_filled_2 FROM with_windows WHERE effective_from > DATE '2024-06-06' AND plan_min_days_since_effective_from > 38) SELECT id, tier_value, plan_min_days_since_effective_from, tier_value_filled, tier_value_filled_2 FROM filtered ORDER BY plan_min_days_since_effective_from DESC, tier_value DESC
